using System;using SASZombieAssaultTD.Engine.Diagnostics;  using System; using System.Collections.Generic;  // Resolve IRenderContext ambiguity using IRenderContext = SASZombieAssaultTD.Engine.Rendering.IRenderContext;  namespace SASZombieAssaultTD.Engine.UI {     /// <summary>     /// Finalizer Program (Program 2) for CASH HUD panel.     /// Single authoritative source for:     /// - Cash panel geometry     /// - Cash panel manual colors     /// - Cash crosshair configuration     /// No baked-in defaults, fallbacks, or flash logic beyond what is explicitly defined here.     /// </summary>     public class HUDPanel_Finalizer : IHUDElement     {         // =====================================================================         // CASH PANEL MANUAL ENTRY AREA (CANONICAL)         // =====================================================================          // Geometry (manual entry surface)         public int cash_X { get; set; } = 100;      /// X Entry (Left and Right movement)          public int cash_Y { get; set; } = 540;      /// Y Entry (Up and Down movement)         public int cash_Width { get; set; } = 75;   /// Width of rectangle (Horizontal size)         public int cash_Height { get; set; } = 22;  /// Height of rectangle (Vertical size)          // Colors (single-field hex or System.Drawing.Color.*)         public string cash_RectManualFillColor { get; set; } = "#FFFFFF";  /// Rectangle Fill Color          public string cash_RectManualTextColor { get; set; } = "#CBCBCB";  /// Rectangle Text Color          // Crosshair (position + shape)         public int cash_CrosshairCenterX { get; set; } = 122;  /// Crosshair X Position          public int cash_CrosshairCenterY { get; set; } = 553;  /// Crosshair Y Position         public int cash_CrosshairArmLength { get; set; } = 3;  /// Crosshair Arm Length         public int cash_CrosshairThickness { get; set; } = 2;  /// Crosshair Line Thickness          // Crosshair colors         public string cash_CrosshairColor { get; set; } = "#CBCBCB";      /// Crosshair Color          public string cash_CrosshairFlashColor { get; set; } = "#FFFFFF"; /// Crosshair Flash Color         public bool cash_CrosshairUseFlash { get; set; } = true;          /// Use Flash Color          // Manual override gate         public bool cash_ManualOverrideEnabled { get; set; } = true;      /// Manual Override Enabled          // =====================================================================         // FINALIZER OUTPUT FIELDS (PROGRAM 2 OUTPUT)         // =====================================================================          public string Id => "cash_panel";          private readonly HUDManager _hudManager;          // Final, normalized geometry used by HUDConfigManager         public int X { get; set; } = 100;          public int Y { get; set; } = 540;         public int Width { get; set; } = 75;         public int Height { get; set; } = 22;          // Final, normalized colors used by HUDPanel_Cash (engine Color: float channels 0–1)         public Color FinalFillColor { get; private set; }          public Color FinalTextColor { get; private set; }          // Manual entry error message (for future UI surfacing)         private string ManualEntryErrorMessage;          // Manual override flag consumed by HUDManager / HUDPanel_Cash         public bool ManualOverrideEnabled { get; private set; } = false;          // Crosshair configuration consumed by HUDManager         public System.Drawing.Color CrosshairColor { get; set; } = System.Drawing.Color.LightBlue;          public bool UseFlashColor { get; set; } = true;         public System.Drawing.Color FlashColor { get; set; } = System.Drawing.Color.Crimson;          public int Layer => 998;          public int CrosshairCenterX { get; set; } = 122;         public int CrosshairCenterY { get; set; } = 553;         public int CrosshairArmLength { get; set; } = 3;         public int CrosshairThickness { get; set; } = 2;          private const string StartingDisplayText = "Zero";          // ---------------------------------------------------------         // Constructors         // ---------------------------------------------------------          public HUDPanel_Finalizer()         {             LoadConfig();         }          public HUDPanel_Finalizer(HUDManager hudManager)         {             _hudManager = hudManager;             LoadConfig();         }          // ---------------------------------------------------------         // Config (LOAD-ONLY + USER-INITIATED SAVE)         // ---------------------------------------------------------          private void LoadConfig()         {             try             {                 HUDConfigManager.LoadPanel("cash_panel", this);                 System.Diagnostics.Debug.WriteLine("[CASH FINALIZER] Config loaded from JSON");             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine($"[CASH FINALIZER] Error loading config: {ex.Message}");             }         }          public void SaveConfig()         {             HUDConfigManager.SetPanel("cash_panel", X, Y, Width, Height, Layer);             HUDConfigManager.SetCrosshair(                 "cash_panel",                 CrosshairCenterX,                 CrosshairCenterY,                 CrosshairArmLength,                 CrosshairThickness,                 CrosshairColor,                 UseFlashColor,                 FlashColor             );              System.Diagnostics.Debug.WriteLine("[CASH FINALIZER] Config saved via HUDConfigManager");         }          // ---------------------------------------------------------         // Manual setters (SaveConfig ONLY here)         // ---------------------------------------------------------          public void SetPanelGeometry(int x, int y, int width, int height)         {             System.Diagnostics.Debug.WriteLine($"[DIAG] HUDPanel_Finalizer.SetPanelGeometry() ENTRY - x={x}, y={y}, width={width}, height={height}");             System.Diagnostics.Debug.WriteLine($"[STATE] Panel geometry CHANGING: from ({X},{Y},{Width},{Height}) to ({x},{y},{width},{height})");              X = x;             Y = y;             Width = width;             Height = height;             SaveConfig();              System.Diagnostics.Debug.WriteLine("[SUCCESS] HUDPanel_Finalizer.SetPanelGeometry() EXIT - geometry updated");         }          public void SetCrosshairPosition(int x, int y)         {             System.Diagnostics.Debug.WriteLine($"[DIAG] HUDPanel_Finalizer.SetCrosshairPosition() ENTRY - x={x}, y={y}");             System.Diagnostics.Debug.WriteLine($"[STATE] Crosshair position CHANGING: from ({CrosshairCenterX},{CrosshairCenterY}) to ({x},{y})");              CrosshairCenterX = x;             CrosshairCenterY = y;             SaveConfig();              System.Diagnostics.Debug.WriteLine("[SUCCESS] HUDPanel_Finalizer.SetCrosshairPosition() EXIT - position updated");         }          public void SetCrosshairSize(int armLength, int thickness)         {             System.Diagnostics.Debug.WriteLine($"[DIAG] HUDPanel_Finalizer.SetCrosshairSize() ENTRY - armLength={armLength}, thickness={thickness}");             System.Diagnostics.Debug.WriteLine($"[STATE] Crosshair size CHANGING: from ({CrosshairArmLength},{CrosshairThickness}) to ({armLength},{thickness})");              CrosshairArmLength = armLength;             CrosshairThickness = thickness;             SaveConfig();              System.Diagnostics.Debug.WriteLine("[SUCCESS] HUDPanel_Finalizer.SetCrosshairSize() EXIT - size updated");         }          public void SetCrosshairColor(System.Drawing.Color color)         {             System.Diagnostics.Debug.WriteLine($"[DIAG] HUDPanel_Finalizer.SetCrosshairColor() ENTRY - color={color}");             System.Diagnostics.Debug.WriteLine($"[STATE] Crosshair color CHANGING: from {CrosshairColor} to {color}");              CrosshairColor = color;             UseFlashColor = false;             SaveConfig();              System.Diagnostics.Debug.WriteLine("[SUCCESS] HUDPanel_Finalizer.SetCrosshairColor() EXIT - color updated");         }          public void EnableFlashColor(bool enable)         {             System.Diagnostics.Debug.WriteLine($"[DIAG] HUDPanel_Finalizer.EnableFlashColor() ENTRY - enable={enable}");             System.Diagnostics.Debug.WriteLine($"[STATE] Flash color enable CHANGING: from {UseFlashColor} to {enable}");              UseFlashColor = enable;             SaveConfig();              System.Diagnostics.Debug.WriteLine("[SUCCESS] HUDPanel_Finalizer.EnableFlashColor() EXIT - flash setting updated");         }          // =====================================================================         // FINALIZER LOGIC (WITH DIAGNOSTICS)         // =====================================================================          public void ProcessEntryData()         {             System.Diagnostics.Debug.WriteLine("=== FINALIZER: ProcessEntryData START ===");              System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] ProcessEntryData() called on instance {GetHashCode()}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] INPUT PARAMETERS RECEIVED:");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Geometry: X={cash_X}, Y={cash_Y}, W={cash_Width}, H={cash_Height}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Fill Color: '{cash_RectManualFillColor}'");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Text Color: '{cash_RectManualTextColor}'");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Override Enabled: {cash_ManualOverrideEnabled}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Crosshair: X={cash_CrosshairCenterX}, Y={cash_CrosshairCenterY}, Length={cash_CrosshairArmLength}");              System.Diagnostics.Debug.WriteLine($"[FINALIZER] cash_ManualOverrideEnabled = {cash_ManualOverrideEnabled}");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] cash_RectManualFillColor = '{cash_RectManualFillColor}'");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] cash_RectManualTextColor = '{cash_RectManualTextColor}'");              if (!cash_ManualOverrideEnabled)             {                 System.Diagnostics.Debug.WriteLine("[FINALIZER] Manual override DISABLED — skipping processing");                 ManualOverrideEnabled = false;                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: ProcessEntryData END ===");                 return;             }              if (!TryParseColorToken(cash_RectManualFillColor, out Color fillColor, out string fillError))             {                 System.Diagnostics.Debug.WriteLine("[FINALIZER] Fill color FAILED validation");                 System.Diagnostics.Debug.WriteLine($"[FINALIZER] Error = {fillError}");                 ManualEntryErrorMessage = fillError;                 ManualOverrideEnabled = false;                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: ProcessEntryData END ===");                 return;             }              System.Diagnostics.Debug.WriteLine("[FINALIZER] Fill color parsed successfully");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] Parsed FillColor = ({fillColor.R:F3},{fillColor.G:F3},{fillColor.B:F3},{fillColor.A:F3})");              if (!TryParseColorToken(cash_RectManualTextColor, out Color textColor, out string textError))             {                 System.Diagnostics.Debug.WriteLine("[FINALIZER] Text color FAILED validation");                 System.Diagnostics.Debug.WriteLine($"[FINALIZER] Error = {textError}");                 ManualEntryErrorMessage = textError;                 ManualOverrideEnabled = false;                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: ProcessEntryData END ===");                 return;             }              System.Diagnostics.Debug.WriteLine("[FINALIZER] Text color parsed successfully");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] Parsed TextColor = ({textColor.R:F3},{textColor.G:F3},{textColor.B:F3},{textColor.A:F3})");              FinalFillColor = fillColor;             FinalTextColor = textColor;             ManualOverrideEnabled = true;              System.Diagnostics.Debug.WriteLine("[FINALIZER] Manual override ENABLED");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] FinalFillColor SET = ({FinalFillColor.R:F3},{FinalFillColor.G:F3},{FinalFillColor.B:F3},{FinalFillColor.A:F3})");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] FinalTextColor SET = ({FinalTextColor.R:F3},{FinalTextColor.G:F3},{FinalTextColor.B:F3},{FinalTextColor.A:F3})");             System.Diagnostics.Debug.WriteLine("=== FINALIZER: ProcessEntryData END ===");         }          private bool TryParseColorToken(string input, out Color engineColor, out string error)         {             System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken START ===");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] Raw input = '{input}'");              engineColor = default;             error = null;              if (string.IsNullOrWhiteSpace(input))             {                 error = "color not found or invalid please try again";                 System.Diagnostics.Debug.WriteLine($"[FINALIZER] PARSE FAILED: {error}");                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");                 return false;             }              input = input.Trim();              if (input.StartsWith("System.Drawing.Color.", StringComparison.Ordinal))             {                 string name = input.Substring("System.Drawing.Color.".Length);                 var sys = System.Drawing.Color.FromName(name);                  if (!sys.IsKnownColor)                 {                     error = "System color not found — please reenter";                     System.Diagnostics.Debug.WriteLine($"[FINALIZER] PARSE FAILED: {error}");                     System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");                     return false;                 }                  engineColor = Color.FromArgb(sys.R / 255f, sys.G / 255f, sys.B / 255f, sys.A / 255f);                 System.Diagnostics.Debug.WriteLine("[FINALIZER] PARSE SUCCESS (System.Drawing.Color)");                 System.Diagnostics.Debug.WriteLine($"[FINALIZER] Parsed Color = ({engineColor.R:F3},{engineColor.G:F3},{engineColor.B:F3},{engineColor.A:F3})");                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");                 return true;             }              string hex = input.StartsWith("#") ? input.Substring(1) : input;              if (hex.Length != 6 && hex.Length != 8)             {                 error = "hex color is invalid";                 System.Diagnostics.Debug.WriteLine($"[FINALIZER] PARSE FAILED: {error}");                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");                 return false;             }              for (int i = 0; i < hex.Length; i++)             {                 char c = hex[i];                 bool ok = (c >= '0' && c <= '9') ||                           (c >= 'A' && c <= 'F') ||                           (c >= 'a' && c <= 'f');                  if (!ok)                 {                     error = "hex color is invalid";                     System.Diagnostics.Debug.WriteLine($"[FINALIZER] PARSE FAILED: {error}");                     System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");                     return false;                 }             }              if (hex.Length == 6)                 hex = "FF" + hex;              byte a = byte.Parse(hex.Substring(0, 2), System.Globalization.NumberStyles.HexNumber);             byte r = byte.Parse(hex.Substring(2, 2), System.Globalization.NumberStyles.HexNumber);             byte g = byte.Parse(hex.Substring(4, 2), System.Globalization.NumberStyles.HexNumber);             byte b = byte.Parse(hex.Substring(6, 2), System.Globalization.NumberStyles.HexNumber);              engineColor = Color.FromArgb(r / 255f, g / 255f, b / 255f, a / 255f);              System.Diagnostics.Debug.WriteLine("[FINALIZER] PARSE SUCCESS (HEX)");             System.Diagnostics.Debug.WriteLine($"[FINALIZER] Parsed Color = ({engineColor.R:F3},{engineColor.G:F3},{engineColor.B:F3},{engineColor.A:F3})");             System.Diagnostics.Debug.WriteLine("=== FINALIZER: TryParseColorToken END ===");             return true;         }          // ---------------------------------------------------------         // Apply Finalizer Colors (WITH DIAGNOSTICS)         // ---------------------------------------------------------          public void ApplyFinalizerColors(HUDPanel_Cash cashPanel)         {             System.Diagnostics.Debug.WriteLine("[DIAG] HUDPanel_Finalizer.ApplyFinalizerColors() ENTRY");              if (cashPanel == null)                 System.Diagnostics.Debug.WriteLine("[NULL] HUDPanel_Finalizer.ApplyFinalizerColors: cashPanel is NULL");              try             {                 System.Diagnostics.Debug.WriteLine("=== FINALIZER: ApplyFinalizerColors START ===");                  if (cashPanel == null)                 {                     System.Diagnostics.Debug.WriteLine("[ERROR] FINALIZER: cashPanel is NULL");                     System.Diagnostics.Debug.WriteLine("=== FINALIZER: ApplyFinalizerColors END ===");                     System.Diagnostics.Debug.WriteLine("[ERROR] HUDPanel_Finalizer.ApplyFinalizerColors() EXIT - with null cashPanel");                     return;                 }                  System.Diagnostics.Debug.WriteLine($"[DIAG] FINALIZER: ManualOverrideEnabled = {ManualOverrideEnabled}");                 System.Diagnostics.Debug.WriteLine($"[DIAG] FINALIZER: FinalFillColor = ({FinalFillColor.R:F3},{FinalFillColor.G:F3},{FinalFillColor.B:F3},{FinalFillColor.A:F3})");                 System.Diagnostics.Debug.WriteLine($"[DIAG] FINALIZER: FinalTextColor = ({FinalTextColor.R:F3},{FinalTextColor.G:F3},{FinalTextColor.B:F3},{FinalTextColor.A:F3})");                  cashPanel.DisplayText = StartingDisplayText;                  if (ManualOverrideEnabled)                 {                     System.Diagnostics.Debug.WriteLine("[DIAG] FINALIZER: Applying manual colors to HUDPanel_Cash");                      cashPanel.ManualFillColor = FinalFillColor;                     cashPanel.ManualTextColor = FinalTextColor;                     cashPanel.UseManualColors = true;                      System.Diagnostics.Debug.WriteLine("[DIAG] FINALIZER: Colors applied successfully");                 }                 else                 {                     cashPanel.UseManualColors = false;                     System.Diagnostics.Debug.WriteLine("[FINALIZER] Override disabled — no colors applied");                 }                  System.Diagnostics.Debug.WriteLine("=== FINALIZER: ApplyFinalizerColors END ===");                 System.Diagnostics.Debug.WriteLine("[DIAG] HUDPanel_Finalizer.ApplyFinalizerColors() EXIT");             }             catch (Exception ex)             {                 System.Diagnostics.Debug.WriteLine("[ERROR] HUDPanel_Finalizer.ApplyFinalizerColors() EXCEPTION");                 System.Diagnostics.Debug.WriteLine($"[ERROR] Exception = {ex.Message}");                 System.Diagnostics.Debug.WriteLine("[DIAG] HUDPanel_Finalizer.ApplyFinalizerColors() EXIT - with exception");             }         }          public void Update(float deltaTime)         {             System.Diagnostics.Debug.WriteLine("[DIAG] HUDPanel_Finalizer.Update - STUB PROCESSED");         }          public void Draw(IRenderContext context)         {             // Finalizer does NOT render.         }          // =====================================================================         // FINALIZER → UISTATE BRIDGE (PROGRAM 2 OUTPUT TO PROGRAM 3 INPUT)         // =====================================================================          public UIState ToUIState()         {             //         // Purpose:             // Convert resolved finalizer data(geometry, colors, crosshair)                 // into a UIState object for the GPU UI pipeline.              // Role:                 // Authoritative source of UIState contents.                 // UIFinalizer consumes this; it does NOT generate elements.             //              // INSTANCE TRACKING: Check if this is the same instance that processed colors             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] ToUIState() called on instance {GetHashCode()}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Current FinalFillColor: R={FinalFillColor.R:F3}, G={FinalFillColor.G:F3}, B={FinalFillColor.B:F3}, A={FinalFillColor.A:F3}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] ManualOverrideEnabled: {ManualOverrideEnabled}");              var state = new UIState();              // ---------------------------------------------------------             // GEOMETRY (resolved)             // ---------------------------------------------------------             state.X = this.X;             state.Y = this.Y;             state.Width = this.Width;             state.Height = this.Height;              // ---------------------------------------------------------             // COLORS (resolved)             // ---------------------------------------------------------             state.FinalFillColor = this.FinalFillColor;             state.FinalTextColor = this.FinalTextColor;              // ---------------------------------------------------------             // CROSSHAIR (resolved)             // ---------------------------------------------------------             state.CrosshairCenterX = this.CrosshairCenterX;             state.CrosshairCenterY = this.CrosshairCenterY;             state.CrosshairArmLength = this.CrosshairArmLength;             state.CrosshairThickness = this.CrosshairThickness;             state.CrosshairColor = this.CrosshairColor;             state.UseFlashColor = this.UseFlashColor;             state.FlashColor = this.FlashColor;              // ---------------------------------------------------------             // ELEMENT LIST INITIALIZATION             // ---------------------------------------------------------             if (state.Elements == null)                     state.Elements = new List<UIRenderable>();              // ---------------------------------------------------------             // ADD CASH PANEL AS A RENDERABLE ELEMENT             // ---------------------------------------------------------             int r = (int)(state.FinalFillColor.R * 255);             int g = (int)(state.FinalFillColor.G * 255);             int b = (int)(state.FinalFillColor.B * 255);             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] COLOR CONVERSION: FinalFillColor=({state.FinalFillColor.R:F3},{state.FinalFillColor.G:F3},{state.FinalFillColor.B:F3}) → RGB=({r},{g},{b})");              var renderable = new UIRenderable             {                 Id = "cash_panel",                 Bounds = new System.Drawing.Rectangle(state.X, state.Y, state.Width, state.Height),                 Color = System.Drawing.Color.FromArgb(                     255,                     r,                     g,                     b                 ),                 Depth = 0,                 Clip = null,                 // FIXED: Assign a proper texture - use MeanStreets.png with correct ID                 TextureId = "map",                 Type = "Panel"             };              System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] CASH PANEL CREATED:");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Bounds: X={state.X}, Y={state.Y}, W={state.Width}, H={state.Height}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] FinalFillColor: R={state.FinalFillColor.R:F3}, G={state.FinalFillColor.G:F3}, B={state.FinalFillColor.B:F3}, A={state.FinalFillColor.A:F3}");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] TextureId: map (should be 'map' for MeanStreets.png)");             System.Diagnostics.Debug.WriteLine($"[HUD FINALIZER] Cash panel ready for GPU rendering pipeline");              return state;         }          // Instance factory methods for HUDConfigManager         public HUDConfigManager.PanelConfig CreatePanelConfig()         {             return new HUDConfigManager.PanelConfig             {                 x = cash_X,                 y = cash_Y,                 width = cash_Width,                 height = cash_Height,                 layer = 998,                 crosshair = CreateCrosshairConfig()             };         }          public HUDConfigManager.CrosshairConfig CreateCrosshairConfig()         {             return new HUDConfigManager.CrosshairConfig             {                 x = cash_CrosshairCenterX,                 y = cash_CrosshairCenterY,                 armLength = cash_CrosshairArmLength,                 thickness = cash_CrosshairThickness,                 color = ParseHexColor(cash_CrosshairColor),                 useFlash = cash_CrosshairUseFlash,                 flashColor = ParseHexColor(cash_CrosshairFlashColor)             };         }          public HUDConfigManager.CrosshairConfig CreateCrosshairConfig(             int x, int y, int armLength, int thickness,             System.Drawing.Color color, bool useFlash, System.Drawing.Color flashColor)         {             return new HUDConfigManager.CrosshairConfig             {                 x = x,                 y = y,                 armLength = armLength,                 thickness = thickness,                 color = color,                 useFlash = useFlash,                 flashColor = flashColor             };         }          /// <summary>         /// Parses hex color string to System.Drawing.Color.         /// </summary>         /// <param name="hex">Hex color string (e.g., "#FF0000").</param>         /// <returns>System.Drawing.Color.</returns>         private static System.Drawing.Color ParseHexColor(string hex)         {             if (string.IsNullOrEmpty(hex) || hex[0] != '#')                 return System.Drawing.Color.Black;              hex = hex.TrimStart('#');             if (hex.Length == 6)                 hex = "FF" + hex;              if (hex.Length != 8)                 return System.Drawing.Color.Black;              try             {                 uint argb = uint.Parse(hex, System.Globalization.NumberStyles.HexNumber);                 return System.Drawing.Color.FromArgb((int)argb);             }             catch             {                 return System.Drawing.Color.Black;             }         }          // Static factory method that returns canonical default crosshair config         // Used for JSON bootstrap / first-run initialization only.         public static HUDConfigManager.CrosshairConfig CreateDefaultCrosshairConfig()         {             return new HUDConfigManager.CrosshairConfig             {                 x = 122,                 y = 553,                 armLength = 3,                 thickness = 2,                 color = ParseHexColor("#CBCBCB"),                 useFlash = true,                 flashColor = ParseHexColor("#FFFFFF")             };         }     } }
